    h.store.events.set('old', {
      ...event,
      eventId: 'old',
      startDate: '2026-08-01',
      endDate: '2026-08-31',
    });
    const readers = [
      jest.spyOn(h.store, 'countReach'),
      jest.spyOn(h.store, 'occupancySeries'),
